def _is_single_paragraph(node: nodes.field_body) -> bool:
    """True if the node only contains one paragraph (and system messages)."""
    if len(node) == 0:
        return False
    elif len(node) > 1:
        for subnode in node[1:]:  # type: Node
            if not isinstance(subnode, nodes.system_message):
                return False
    if isinstance(node[0], nodes.paragraph):
        return True
    return False


def _split_type_and_name(fieldarg: str) -> Tuple[str, str]:
    """Split a field argument like "dict(str, str) name" into type and name,
    respecting balanced parentheses/brackets so that commas and spaces inside
    type expressions like ``dict(str, str)`` are not used as split points."""
    depth = 0
    for i, c in enumerate(fieldarg):
        if c in '([':
            depth += 1
        elif c in ')]':
            depth -= 1
        elif c.isspace() and depth == 0:
            argtype = fieldarg[:i].strip()
            argname = fieldarg[i:].strip()
            if argtype and argname:
                return argtype, argname
            break
    raise ValueError('field argument has no type/name pair')


